<?php
namespace Tivoli\Service;
use Tivoli\Repository\PurchaseAccounting as A;
use Tivoli\Domain\Stay\StayRules as R;
use Tivoli\Security\PermissionDenied;
use RuntimeException;

final class PurchaseCorrectionService
{
    use PurchaseCorrectionPosting;
    public function __construct(private readonly AccessService $access,private readonly ?string $clock=null){}
    private function now():string{return $this->clock??gmdate('Y-m-d H:i:s');}
    private function hash(mixed $v):string{return hash('sha256',json_encode($v,JSON_THROW_ON_ERROR));}
    private function id(string $v):int{if(!preg_match('/^[1-9][0-9]{0,17}$/D',$v))throw new RuntimeException('Choose a valid source.');return (int)$v;}
    public function permit(int $actor):void{(new PurchaseService($this->access,$this->now()))->permit($actor);}
    public function owner(int $actor):bool{return (new FinanceService($this->access,$this->now()))->canPostLate($actor)&&(new ExpenseService($this->access))->canManage($actor);}
    private function timestamp(string $v):string{$v=str_replace('T',' ',R::text($v,19,true));if(strlen($v)===16)$v.=':00';$dt=\DateTimeImmutable::createFromFormat('!Y-m-d H:i:s',$v,new \DateTimeZone('UTC'));if(!$dt||$dt->format('Y-m-d H:i:s')!==$v||$v>$this->now()||$v<'2000-01-01 00:00:00')throw new RuntimeException('Enter a valid actual UTC time no later than now.');return $v;}
    public function source(int $actor,string $type,int $id):array{
        $this->permit($actor);$r=$this->access->repo;$blocks=[];$stockBlocks=[];$expense=null;$movement=null;$extra=null;$qty=0;$stock=null;$context=[];
        if($type==='purchase'){
            $case=(new PurchaseService($this->access,$this->now()))->detail($actor,$id);if($case['status']!=='posted'||!$case['expense_id'])throw new RuntimeException('Choose an officially posted purchase.');$blocks=array_merge($blocks,$case['settlement_blockers']);$expense=(int)$case['expense_id'];$base=$r->run('SELECT * FROM expenses WHERE id=?',[$expense])->fetch();if(!$base)throw new RuntimeException('Linked original cost is missing.');$cost=R::minor((string)$base['amount']);$root=$case['root'];$supplier=$case['scope']['supplier'];$category=(int)$base['category_id'];$method=$base['method'];$date=substr($case['receipt']['delivered_at'],0,10);$ceiling=max($case['limit'],$cost);$context=[$root,$case['history'],$base];
            if($root['data']['type']==='stock'){$qty=(int)$root['data']['qty'];$extra=(int)$root['data']['extra_id'];$movement=$case['stock_movement_id']?(int)$case['stock_movement_id']:null;$m=$movement?$r->run('SELECT * FROM stock_movements WHERE id=?',[$movement])->fetch():null;
                if(!$m||$m['movement_type']!=='in'||$m['ref_type']!=='purchase'||(int)$m['ref_id']!==$id||(int)$m['extra_id']!==$extra||R::quantity((string)$m['qty'])!==$qty)$stockBlocks[]='The original stock receipt/source link is unsupported; do not infer a matching movement.';
                $row=$r->run('SELECT e.id,e.name,e.stock_qty,COALESCE(s.tracked,1) tracked FROM extras e LEFT JOIN stay_extra_settings s ON s.extra_id=e.id WHERE e.id=?',[$extra])->fetch();if(!$row||!$row['tracked'])$stockBlocks[]='The original item is no longer tracked stock.';$stock=$row?['row'=>$row,'minor'=>R::quantity((string)$row['stock_qty']),'rows'=>$r->run('SELECT * FROM stock_movements WHERE extra_id=? ORDER BY id',[$extra])->fetchAll()]:null;$context[]=[$m,$extra?\Tivoli\Repository\StockAvailability::hold($r,(int)$extra):null];
            }
        }elseif($type==='provider'){
            $root=$r->run("SELECT e.*,u.name actor_name FROM finance_events e JOIN users u ON u.id=e.actor_id WHERE e.id=? AND e.kind='provider_requested' AND e.target_type='provider'",[$id])->fetch();if(!$root)throw new RuntimeException('Provider request not found.');if(!$this->owner($actor)&&(int)$root['actor_id']!==$actor)throw new PermissionDenied('Only requester and configured owner may review this provider source.');$root['data']=json_decode($root['payload'],true,512,JSON_THROW_ON_ERROR);$review=$r->run("SELECT * FROM finance_events WHERE kind='request_approved' AND target_type='request' AND target_id=? ORDER BY id",[(string)$id])->fetchAll();if(count($review)!==1)throw new RuntimeException('Choose an approved provider cost with supported review evidence.');$cost=(int)$review[0]['amount_minor'];if($cost!==(int)$root['amount_minor']||$cost!==(int)$root['data']['payable'])$blocks[]='Original provider cost/payable evidence differs; separate reconciliation is required.';$supplier=$root['data']['payee'];$category=null;$method='momo';$date=$root['effective_date'];$ceiling=$cost;$context=[$root,$review];
        }else throw new RuntimeException('Choose Purchase Request or Legacy Provider.');
        $payments=A::paymentRows($r,$type,$id,$expense);$position=A::position($r,$type,$id,$cost,$payments,$qty,$expense);$moneyBlocks=[];if($type==='purchase'&&$case['settlement_blockers']){$position['paid']=$case['paid'];$position['payable']=max(0,$position['cost']-$case['paid']);$position['supplier_due']=max(0,$case['paid']-$position['cost']);}
        foreach($position['payments'] as &$payment){$d=$payment['data'];$issues=[];$payer=$d['paid_by']??$d['actual_payer_id']??null;$actual=$d['actual_paid_at']??null;if(!$payer||!$r->user((int)$payer)||!$actual||!trim($d['evidence']??''))$issues[]='Actual original payer, time and independent payout evidence are not established.';if(!in_array($d['method']??'', ['cash','momo'],true))$issues[]='Historical payout method is unsupported.';if(($d['method']??'')==='cash'&&($d['cash_funding']??'')!=='separate_from_full_sales_deposit')$issues[]='Separate cash funding must be established.';
            if($type==='purchase'){$marker=$r->run("SELECT * FROM finance_events WHERE id=? AND kind='purchase_paid' AND target_type='purchase' AND target_id=?",[(int)($d['purchase_payment_id']??0),(string)$id])->fetch();$original=$marker?json_decode($marker['payload'],true,512,JSON_THROW_ON_ERROR):[];if(!$marker||(int)($d['purchase_id']??0)!==$id||(int)($original['amount']??-1)!==$payment['original_amount']||($original['method']??'')!==($d['method']??'')||($original['reference']??'')!==($d['reference']??'')||(int)($original['payer_id']??0)!==(int)$payer)$issues[]='Original purchase payout and settlement links do not reconcile.';$context[]=$marker;}
            $payment['blockers']=$issues;$moneyBlocks=array_merge($moneyBlocks,$issues);
        }unset($payment);
        if(!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$date))$blocks[]='Original activity date is unknown.';$followups=$r->run("SELECT e.*,u.name actor_name FROM finance_events e JOIN users u ON u.id=e.actor_id WHERE e.target_type='purchase_source' AND e.target_id=? AND e.kind IN ('pc_followup','pc_settled') ORDER BY e.id",[$type.':'.$id])->fetchAll();foreach($followups as &$row)$row['data']=json_decode($row['payload'],true,512,JSON_THROW_ON_ERROR);unset($row);$token=$this->hash([$context,$payments,$position,$stock,$followups]);return $position+['followups'=>$followups]+['source_type'=>$type,'source_id'=>$id,'root'=>$root,'supplier'=>$supplier,'expense_id'=>$expense,'category_id'=>$category,'cost_method'=>$method,'original_cost'=>$cost,'original_qty'=>$qty,'movement_id'=>$movement,'extra_id'=>$extra,'stock'=>$stock,'ceiling'=>$ceiling,'original_date'=>$date,'blockers'=>$blocks,'stock_blockers'=>$stockBlocks,'money_blockers'=>array_values(array_unique($moneyBlocks)),'token'=>$token];
    }
    private function event(int $actor,string $kind,int|string $id,array $data,int $amount=0,string $target='purchase_correction'):int{$r=$this->access->repo;$now=$this->now();$r->run('INSERT INTO finance_events(kind,target_type,target_id,amount_minor,effective_date,actor_id,payload,created_at) VALUES(?,?,?,?,?,?,?,?)',[$kind,$target,(string)$id,$amount,substr($now,0,10),$actor,json_encode($data,JSON_THROW_ON_ERROR),$now]);return (int)$r->db->lastInsertId();}
    private function active(string $type,int $source):bool{return (bool)$this->access->repo->run("SELECT root.id FROM finance_events root WHERE root.kind='pc_requested' AND JSON_UNQUOTE(JSON_EXTRACT(root.payload,'$.source_type'))=? AND JSON_UNQUOTE(JSON_EXTRACT(root.payload,'$.source_id'))=? AND NOT EXISTS(SELECT 1 FROM finance_events decision WHERE decision.target_type='purchase_correction' AND decision.target_id=CAST(root.id AS CHAR CHARACTER SET utf8mb4) COLLATE utf8mb4_unicode_ci AND decision.kind IN ('pc_approved','pc_rejected','pc_withdrawn')) LIMIT 1",[$type,(string)$source])->fetchColumn();}
    private function load(int $actor,int $id):array{
        $this->permit($actor);$r=$this->access->repo;$root=$r->run("SELECT e.*,u.name actor_name FROM finance_events e JOIN users u ON u.id=e.actor_id WHERE e.id=? AND e.kind='pc_requested' AND e.target_type='purchase_correction'",[$id])->fetch();if(!$root)throw new RuntimeException('Purchase correction not found.');if(!$this->owner($actor)&&(int)$root['actor_id']!==$actor)throw new PermissionDenied('Only requester and configured owner may view this private correction.');$root['data']=json_decode($root['payload'],true,512,JSON_THROW_ON_ERROR);$history=$r->run("SELECT e.*,u.name actor_name FROM finance_events e JOIN users u ON u.id=e.actor_id WHERE e.target_type='purchase_correction' AND e.target_id=? ORDER BY e.id",[(string)$id])->fetchAll();$proposal=$root['data']['proposal'];$status='pending';$revisions=[$root];$posted=null;foreach($history as &$e){$e['data']=json_decode($e['payload'],true,512,JSON_THROW_ON_ERROR);switch($e['kind']){case 'pc_revised':$proposal=$e['data']['proposal'];$revisions[]=$e;$status='pending';break;case 'pc_returned':$status='returned';break;case 'pc_rejected':$status='rejected';break;case 'pc_withdrawn':$status='withdrawn';break;case 'pc_approved':$status='posted';$posted=$e['data'];break;}}unset($e);return compact('root','history','proposal','status','revisions','posted')+['version'=>$this->hash([$id,array_column($history,'id')])];
    }
    public function detail(int $actor,int $id):array{$c=$this->load($actor,$id);$p=$c['proposal'];$c['live']=$this->source($actor,$p['source_type'],$p['source_id']);$c['stale']=!hash_equals($p['source_token'],$c['live']['token']);return $c;}
    public function execute(int $actor,string $action,array $in,string $key):array{
        try{$this->permit($actor);if(!preg_match('/^[a-f0-9]{32}$/D',$key))throw new RuntimeException('Reload this form identity.');$file=null;if(isset($in['_evidence'])){if(!in_array($action,['request','revise','followup','settle'],true))throw new RuntimeException('Evidence belongs on a request, revision, follow-up or actual settlement.');$file=FinanceAttachment::checked($in['_evidence']);unset($in['_evidence']);}foreach($in as $v)if(!is_string($v))throw new RuntimeException('Invalid linked correction form.');unset($in['csrf'],$in['operation_key'],$in['action']);ksort($in);$fp=$this->hash(['purchase_correction.'.$action,$in,$file?FinanceAttachment::meta($file):null]);return $this->access->transaction(function()use($actor,$action,$in,$key,$fp,$file){$this->permit($actor);$r=$this->access->repo;$old=$r->run('SELECT * FROM finance_operations WHERE actor_id=? AND operation_key=?',[$actor,$key])->fetch();if($old){if(!hash_equals($old['fingerprint'],$fp))throw new RuntimeException('This key belongs to different details.');$event=$r->run('SELECT * FROM finance_events WHERE id=?',[$old['event_id']])->fetch();if(!$event||!str_starts_with($event['kind'],'pc_'))throw new RuntimeException('This key belongs to another workflow.');$d=json_decode($event['payload'],true,512,JSON_THROW_ON_ERROR);if(in_array($action,['post','return','reject','settle'],true)&&!$this->owner($actor))throw new PermissionDenied('Owner authority is required for replay.');if($event['target_type']==='purchase_source'){$this->source($actor,$d['source_type'],(int)$d['source_id']);return ['id'=>0,'source_type'=>$d['source_type'],'source_id'=>(int)$d['source_id'],'event_id'=>(int)$event['id'],'replayed'=>true];}$id=$event['kind']==='pc_requested'?(int)$event['id']:(int)$event['target_id'];$this->load($actor,$id);return ['id'=>$id,'event_id'=>(int)$event['id'],'replayed'=>true];}
            $out=$this->command($actor,$action,$in);if($file)FinanceAttachment::save($this->access,$actor,'purchasecorrection',$out['event_id'],$file);$r->run('INSERT INTO finance_operations VALUES(?,?,?,?)',[$actor,$key,$fp,$out['event_id']]);$this->access->audit($actor,'purchase_correction.'.$action,'purchase_correction',(string)$out['id'],'succeeded',['event_id'=>$out['event_id']]);return $out+['replayed'=>false];});
        }catch(\Throwable $e){$this->access->audit($actor,'purchase_correction.failed','purchase_correction',null,'denied',['action'=>substr($action,0,32)]);throw $e;}
    }
    public function register(int $actor,string $page='requests',int $before=0):array{$this->permit($actor);if($page==='review'&&!$this->owner($actor))throw new PermissionDenied('Owner review is restricted.');$where='';$params=[];if(!$this->owner($actor)){$where.=' AND actor_id=?';$params[]=$actor;}if($before){$where.=' AND id<?';$params[]=$before;}$terminal="EXISTS(SELECT 1 FROM finance_events decision WHERE decision.target_type='purchase_correction' AND decision.target_id=CAST(root.id AS CHAR CHARACTER SET utf8mb4) COLLATE utf8mb4_unicode_ci AND decision.kind IN ('pc_approved','pc_rejected','pc_withdrawn'))";if($page==='log')$where.=' AND '.$terminal;if($page==='review')$where.=" AND COALESCE((SELECT state.kind FROM finance_events state WHERE state.target_type='purchase_correction' AND state.target_id=CAST(root.id AS CHAR CHARACTER SET utf8mb4) COLLATE utf8mb4_unicode_ci AND state.kind IN ('pc_revised','pc_returned','pc_approved','pc_rejected','pc_withdrawn') ORDER BY state.id DESC LIMIT 1),'pc_requested') IN ('pc_requested','pc_revised')";$ids=$this->access->repo->run("SELECT root.id FROM finance_events root WHERE root.kind='pc_requested' AND root.target_type='purchase_correction'".$where.' ORDER BY id DESC LIMIT 51',$params)->fetchAll(\PDO::FETCH_COLUMN);$more=count($ids)>50;if($more)array_pop($ids);$rows=[];foreach($ids as $id){$c=$this->detail($actor,(int)$id);if($page==='review'&&$c['status']!=='pending'||$page==='log'&&!in_array($c['status'],['posted','rejected','withdrawn'],true))continue;$rows[]=$c;}return ['rows'=>$rows,'next'=>$more?(int)end($ids):0];}
    public function providerOutstanding(int $actor,bool $ownOnly=false):array{
        $this->permit($actor);$rows=[];$where=$ownOnly||!$this->owner($actor)?' AND root.actor_id=?':'';$params=$where?[$actor]:[];
        $ids=$this->access->repo->run("SELECT DISTINCT root.id FROM finance_events root JOIN finance_events fix ON fix.kind='pc_posted' AND JSON_UNQUOTE(JSON_EXTRACT(fix.payload,'$.source_type'))='provider' AND JSON_UNQUOTE(JSON_EXTRACT(fix.payload,'$.source_id'))=CAST(root.id AS CHAR CHARACTER SET utf8mb4) COLLATE utf8mb4_unicode_ci WHERE root.kind='provider_requested'".$where.' ORDER BY root.id',$params)->fetchAll(\PDO::FETCH_COLUMN);
        foreach($ids as $id){$v=$this->source($actor,'provider',(int)$id);if($v['supplier_due']>0)$rows[]=['source_id'=>(int)$id,'supplier'=>$v['supplier'],'supplier_due'=>$v['supplier_due']];}return $rows;
    }
    public function attentionCount(int $actor):int{$this->permit($actor);if(!$this->owner($actor))throw new PermissionDenied('Owner review is restricted.');return (int)$this->access->repo->run("SELECT COUNT(*) FROM finance_events root WHERE root.kind='pc_requested' AND NOT EXISTS(SELECT 1 FROM finance_events decision WHERE decision.target_type='purchase_correction' AND decision.target_id=CAST(root.id AS CHAR CHARACTER SET utf8mb4) COLLATE utf8mb4_unicode_ci AND decision.kind IN ('pc_approved','pc_rejected','pc_withdrawn'))")->fetchColumn()+count($this->providerOutstanding($actor));}
}
